// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Adopt and discard in the editor"
// Changes: The adopt dialog's choices follow the changes module's flags; the definition/grammar-rules warning.

import { describe, expect, it } from 'vitest'
import { adoptChoices, initialSelection, pairingWarning } from './adoption'
import { draftChanges } from './changes'
import type { Parts } from './parts'

const parts = (over: Partial<Parts> = {}): Parts => ({
  definition: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  grammarRules: 'E -> id',
  precTable: { terminals: ['+'], cells: {} },
  reductionRules: 'E -> id',
  ...over,
})

describe('the adopt dialog choices', () => {
  it('unchanged parts cannot be ticked; changed ones are ticked; changed on both sides start unticked with a warning', () => {
    const base = parts()
    const project = parts({ reductionRules: 'E -> E + E' })
    const draft = parts({ grammarRules: 'E -> id + E', reductionRules: 'E -> id + id' })
    const choices = adoptChoices(draftChanges({ draft, project, base }))

    expect(choices).toEqual({
      definition: { selectable: false, bothSides: false },
      grammarRules: { selectable: true, bothSides: false },
      precTable: { selectable: false, bothSides: false },
      reductionRules: { selectable: true, bothSides: true },
    })
    expect(initialSelection(choices)).toEqual(['grammarRules'])
  })

  it('warns when the definition is adopted without changed grammar rules, or the other way round', () => {
    const draft = parts({ definition: { nonterminals: 'E T', terminals: 'id', start: 'E' }, grammarRules: 'E -> T' })
    const choices = adoptChoices(draftChanges({ draft, project: parts(), base: parts() }))

    expect(pairingWarning(choices, ['definition'])).toMatch(/Definíciu bez gramatických pravidiel/)
    expect(pairingWarning(choices, ['grammarRules'])).toMatch(/Gramatické pravidlá bez definície/)
    expect(pairingWarning(choices, ['definition', 'grammarRules'])).toBeNull()
    expect(pairingWarning(choices, [])).toBeNull()
  })

  it('no warning when the other part has nothing to adopt', () => {
    const draft = parts({ grammarRules: 'E -> id + E' })
    const choices = adoptChoices(draftChanges({ draft, project: parts(), base: parts() }))
    expect(pairingWarning(choices, ['grammarRules'])).toBeNull()
  })
})
